""C:\\Users\\labops\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$base='"'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/'
function Q("'$term){
  $u = $base + '"'esearch.fcgi?db=pubmed&retmode=json&retmax=6&sort=relevance&term=' + [uri]::EscapeDataString("'$term)
  try { $r = Invoke-RestMethod -Uri $u -TimeoutSec 40 } catch { Write-Output "FAIL: $term :: $_"; return $null }
  return $r.esearchresult.idlist
}
$queries = [ordered]@{
 '"'HRV_recovery' = 'heart rate variability AND recovery AND athlete AND monitoring'
 'CMJ_neuromuscular' = 'countermovement jump AND neuromuscular fatigue AND recovery'
 'RPE_load' = 'rating of perceived exertion AND training load AND monitoring'
 'HRV_guided' = 'heart rate variability guided training AND endurance'
 'HRV_reliability' = 'heart rate variability measurement reliability AND athletes'
 'CMJ_sensitivity' = 'countermovement jump reliability AND fatigue AND team sport'
}
"'$out = @{}
foreach($k in $queries.Keys){
  $ids = Q $queries[$k]
  $out[$k] = $ids
  Write-Output ("{0} => {1}" -f $k, ($ids -join '"','))
}
"'$all = ($out.Values | ForEach-Object {$_}) | Sort-Object -Unique | Where-Object {$_}
Write-Output "ALL:$($all -join '"',')\"
Set-Content -LiteralPath 'pmids.txt' -Value ("'$all -join "`n")'"

""C:\\Users\\labops\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$ids = (Get-Content -LiteralPath '"'pmids.txt') -join ','
"'$u = '"'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?db=pubmed&retmode=json&id=' + "'$ids
$r = Invoke-RestMethod -Uri $u -TimeoutSec 60
$rows = foreach($id in $r.result.uids){
  $a = $r.result.$id
  [pscustomobject]@{
    pmid = $id
    year = $a.pubdate
    journal = $a.source
    title = $a.title
    doi = (($a.articleids | Where-Object {$_.idtype -eq '"'doi'}).value)
  }
}
"'$rows | Sort-Object pmid | ForEach-Object { "{0} | {1} | {2} | {3} | doi:{4}" -f $_.pmid,$_.year,$_.journal,$_.title,$_.doi }
$rows | Export-Csv -LiteralPath '"'refs.csv' -NoTypeInformation -Encoding UTF8""

